pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 reentrantDeposit, uint256 topupAmount) public {
        // Keep amounts in a range where arithmetic does not overflow and a balance can be covered
        vm.assume(initialDeposit > 0 && initialDeposit <= type(uint128).max);
        vm.assume(reentrantDeposit > 0 && reentrantDeposit <= type(uint128).max);
        vm.assume(topupAmount > 0 && topupAmount <= type(uint128).max);
        vm.assume(initialDeposit + reentrantDeposit <= type(uint128).max);
        vm.assume(initialDeposit + topupAmount <= type(uint128).max);

        // Deploy an adversarial re-entrant caller that calls addToBalance during its receive hook
        Attacker attacker = new Attacker(address(c));
        address attackerAddr = address(attacker);

        // First, give the attacker some balance so it can deposit
        vm.deal(attackerAddr, initialDeposit + reentrantDeposit + 1 ether);

        // Let attacker make an initial deposit (top-level)
        vm.prank(attackerAddr);
        c.addToBalance{value: initialDeposit}();

        // Now the attacker withdraws — its receive hook will call addToBalance again with reentrantDeposit
        // The attacker needs enough Ether to make the reentrant deposit; it already has it from the deal
        vm.prank(attackerAddr);
        c.withdrawBalance(); // this triggers receive -> addToBalance

        // At this point, in the reference C the nonReentrant modifier would have prevented the reentrant addToBalance.
        // In the buggy version, addToBalance executed reentrantly, reading userBalance[attacker] before it was zeroed.
        // We record the attacker's balance after the reentrant chaos.
        uint256 balanceBeforeTopup = c.getBalance(attackerAddr);

        // Now make a simple top-level deposit (different amount) — the invariant we check is that this top-level deposit always succeeds and increases the balance by exactly topupAmount.
        // Since the contract may still be locked in the buggy version after the reentrancy, we use try/catch to observe whether the call succeeds.
        vm.deal(attackerAddr, topupAmount); // ensure attacker can pay
        vm.prank(attackerAddr);
        (bool success, ) = address(c).call{value: topupAmount}(abi.encodeWithSignature("addToBalance()"));

        if (success) {
            uint256 balanceAfter = c.getBalance(attackerAddr);
            // Top-level deposit must increase the balance by exactly topupAmount
            assertEq(balanceAfter, balanceBeforeTopup + topupAmount);
        } else {
            // The reference C NEVER reverts a top-level addToBalance after a successful withdrawal.
            // The buggy version may be locked and revert. We fail the test if the reference reverts here (it doesn't).
            // Since we cannot distinguish contracts inside this try, we must ensure the reference passes.
            // We wrap the reference behaviour expectation by running the same scenario on a fresh reference?
            // Actually, the rule is: for any admissible history, a subsequent top-level addToBalance MUST succeed and increase the balance by exactly topupAmount.
            // In the reference it always succeeds; in the buggy it may revert. Therefore a revert indicates a bug.
            assertTrue(false, "Reference should never revert a top-level deposit after withdrawal");
        }
    }
}

contract Attacker {
    C public target;
    bool private reentered;

    constructor(address _target) {
        target = C(_target);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // The msg.sender inside receive is the target C contract, but the attacker address is address(this).
            // We need the reentrant call to addToBalance to come from the same attacker address.
            // The target's withdrawBalance does a low-level call to msg.sender (which is this contract).
            // During this receive, msg.sender for the following call is this attacker contract itself.
            // So we can simply call addToBalance directly.
            // Use the Ether we received from withdrawBalance (which is exactly initialDeposit) plus some extra sent earlier.
            target.addToBalance{value: msg.value}();
        }
    }
}

